int charge_steps(int level, int target) {
    int steps = 0;
    while (level < target) {
        level += 7;
        steps++;
    }
    return steps;
}

int charge_steps(int level, int target) {
    int steps = 0;
    for (; level < target; steps++) {
        level = level + 7;
    }
    return steps;
}

int charge_steps(int level, int target) {
    int steps = 0;
    int now = level;
    while (now < target) {
        now += 7;
        steps = steps + 1;
    }
    return steps;
}
